        proof.debit(TokenValueClassV16::AccountCapital, capital_paid)?;
        proof.debit(TokenValueClassV16::ResolvedPayoutPaid, resolved_payout_paid)?;
        proof.credit(TokenValueClassV16::ExternalQuote, total_external_out)?;
        Ok(proof)
